'use client';

import { motion, type Transition } from 'motion/react';
import { useState } from 'react';

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { hold } from '@/registry/ndeko/lib/demonstration';
import {
  Link2Icon,
  MailIcon,
  MousePointerClickIcon,
  SearchIcon,
  Share2Icon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import {
  EASE_IN_OUT_STRONG,
  INSTANT,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { ChartCard } from './_parts/chart-card';
import {
  ROUNDED_ENDS,
  ROUNDED_LEFT,
  ROUNDED_RIGHT,
  ROUNDED_TOP,
} from './_parts/corners';
import { DataTable, type DataRow } from './_parts/data-table';
import { formatCount } from './_parts/format';
import { percentOf } from './_parts/scale';
import { useChartDemo } from './_parts/use-chart-demo';
import { WrappingRoll } from './_parts/wrapping-roll';

export type ShiftView = 'list' | 'bars' | 'change';

export type ShiftSource = {
  id: string;
  name: string;
  icon: Icon;
  value: number;
  /** The change against the period before, as a whole percentage. Below zero when it fell. */
  change: number;
};

export type SourceShiftProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  sources: readonly ShiftSource[];
  view: ShiftView;
  onViewChange: (view: ShiftView) => void;
  /** What the values count, in the plural: "visits". */
  unit: string;
  /** The period the values cover: "this week". */
  period: string;
  className?: string;
};

const VIEWS: Segment<ShiftView>[] = [
  { value: 'list', label: 'List' },
  { value: 'bars', label: 'Bars' },
  { value: 'change', label: 'Change' },
];

/** The height of the tallest bar when the sources stand side by side. */
const BAR_AREA_PX = 116;

const GLIDE: Transition = {
  layout: { duration: 0.42, ease: EASE_IN_OUT_STRONG },
};

const NO_GLIDE: Transition = { layout: INSTANT };

function glideOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return NO_GLIDE;
  }
  return GLIDE;
}

type ViewClasses = {
  list: string;
  item: string;
  icon: string;
  name: string;
  value: string;
  change: string;
  bar: string;
  /** The line a change is measured from. Only the change view draws it. */
  zero: string;
};

/**
 * One set of elements, three places for each of them. A view only says where an element sits, so
 * switching view moves what is already there instead of drawing it again.
 */
const VIEW_CLASSES: Record<ShiftView, ViewClasses> = {
  list: {
    list: 'flex flex-col',
    item: 'grid grid-cols-[auto_minmax(0,1fr)_auto_2.5rem] items-center gap-x-2 gap-y-1 py-1.5 @xs:grid-cols-[auto_minmax(0,1fr)_auto_3rem] @xs:gap-x-3',
    icon: 'row-span-2',
    name: 'col-start-2 row-start-1 truncate text-[13px]',
    value: 'col-start-3 row-start-1 text-[13px] font-medium',
    change:
      'text-muted-foreground col-start-4 row-start-1 justify-self-end text-xs',
    bar: 'col-start-2 col-end-5 row-start-2 h-1 justify-self-start',
    zero: 'hidden',
  },
  bars: {
    list: 'grid items-end gap-1.5',
    item: 'flex min-w-0 flex-col items-center gap-1.5',
    icon: 'order-3',
    name: 'sr-only order-4 text-center text-[11px] @sm:not-sr-only @sm:w-full @sm:truncate',
    value: 'order-1 text-xs font-medium @sm:text-[13px]',
    change: 'text-muted-foreground order-5 text-[11px]',
    bar: 'order-2 w-6 max-w-full',
    zero: 'hidden',
  },
  change: {
    list: 'flex flex-col',
    item: 'grid grid-cols-[auto_4.5rem_minmax(0,1fr)_2.5rem] items-center gap-x-2 py-1.5 @xs:grid-cols-[auto_5.5rem_minmax(0,1fr)_3rem] @xs:gap-x-3',
    icon: 'row-span-2',
    name: 'col-start-2 row-start-1 truncate text-[13px]',
    value: 'text-muted-foreground col-start-2 row-start-2 text-[11px]',
    change:
      'col-start-4 row-span-2 row-start-1 justify-self-end text-[13px] font-medium',
    bar: 'col-start-3 row-span-2 row-start-1 h-3 justify-self-start',
    zero: 'bg-foreground/20 col-start-3 row-span-2 row-start-1 h-full w-px justify-self-center',
  },
};

function largestOf(values: readonly number[]) {
  let largest = 1;
  for (const value of values) {
    largest = Math.max(largest, value);
  }
  return largest;
}

type Bounds = {
  /** The largest value, and the largest change whichever way it went. */
  value: number;
  change: number;
};

function boundsOf(sources: readonly ShiftSource[]): Bounds {
  const values = sources.map((source) => source.value);
  const changes = sources.map((source) => Math.abs(source.change));
  return { value: largestOf(values), change: largestOf(changes) };
}

/** A change grows from the middle of its track: to the right when it rose, to the left when it fell. */
function changeBarOf(source: ShiftSource, bounds: Bounds): React.CSSProperties {
  const size = Math.abs(source.change);
  const reach = size / bounds.change;
  const half = reach * 0.5;
  const width = percentOf(half);
  if (source.change >= 0) {
    return { marginLeft: '50%', width, ...ROUNDED_RIGHT };
  }
  const start = 0.5 - half;
  return { marginLeft: percentOf(start), width, ...ROUNDED_LEFT };
}

function barStyleOf(
  source: ShiftSource,
  view: ShiftView,
  bounds: Bounds
): React.CSSProperties {
  const share = source.value / bounds.value;
  if (view === 'bars') {
    const height = share * BAR_AREA_PX;
    return { height, ...ROUNDED_TOP };
  }
  if (view === 'change') {
    return changeBarOf(source, bounds);
  }
  return { width: percentOf(share), ...ROUNDED_ENDS };
}

/** In the change view a bar says which way a source went, so it takes the colour of that way. */
function barToneOf(source: ShiftSource, view: ShiftView) {
  const hasFallen = source.change < 0;
  const showsChange = view === 'change';
  if (hasFallen && showsChange) {
    return 'bg-destructive';
  }
  return 'bg-primary';
}

function changeTextOf(change: number) {
  if (change > 0) {
    return `+${change}%`;
  }
  return `${change}%`;
}

/** The sources in the order a view reads them: the largest first, or the fastest riser first. */
function orderedFor(view: ShiftView, sources: readonly ShiftSource[]) {
  const ordered = [...sources];
  if (view === 'change') {
    return ordered.sort((first, second) => second.change - first.change);
  }
  return ordered.sort((first, second) => second.value - first.value);
}

type Reading = {
  headline: string;
  detail: string;
};

function fallOf(source: ShiftSource | undefined) {
  const hasFallen = source !== undefined && source.change < 0;
  if (!hasFallen) {
    return 'No source fell';
  }
  const size = Math.abs(source.change);
  return `${source.name} fell the most, down ${size}%`;
}

/** The view in two lines: what leads, then the figure behind it. */
function readingOf(
  view: ShiftView,
  sources: readonly ShiftSource[],
  unit: string,
  period: string
): Reading {
  const byValue = orderedFor('list', sources);
  const byChange = orderedFor('change', sources);
  const largest = byValue.at(0);
  const riser = byChange.at(0);
  const faller = byChange.at(-1);
  const hasSources = largest !== undefined && riser !== undefined;
  if (!hasSources) {
    return { headline: 'No source yet', detail: '' };
  }
  if (view === 'change') {
    return {
      headline: `${riser.name} grew the fastest, up ${riser.change}%`,
      detail: fallOf(faller),
    };
  }
  const amount = formatCount(largest.value);
  return {
    headline: `${largest.name} brings the most ${unit}`,
    detail: `${amount} ${period}`,
  };
}

function listStyleOf(view: ShiftView, count: number) {
  if (view === 'bars') {
    return { gridTemplateColumns: `repeat(${count}, minmax(0, 1fr))` };
  }
  return undefined;
}

type SourceItemProps = {
  source: ShiftSource;
  view: ShiftView;
  bounds: Bounds;
  transition: Transition;
};

/** Every part of a source keeps its element from one view to the next, and glides to its new place. */
function SourceItem({ source, view, bounds, transition }: SourceItemProps) {
  const classes = VIEW_CLASSES[view];
  const SourceIcon = source.icon;

  return (
    <li className={classes.item}>
      <motion.span
        layout='position'
        layoutDependency={view}
        transition={transition}
        aria-hidden='true'
        className={cn(
          'keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md',
          classes.icon
        )}
      >
        <SourceIcon className='size-3.5' />
      </motion.span>
      <motion.span
        layout='position'
        layoutDependency={view}
        transition={transition}
        className={cn('min-w-0', classes.name)}
      >
        {source.name}
      </motion.span>
      <motion.span
        layout='position'
        layoutDependency={view}
        transition={transition}
        className={cn(
          'tabular-nums transition-colors duration-200',
          classes.value
        )}
      >
        {formatCount(source.value)}
      </motion.span>
      <motion.span
        layout='position'
        layoutDependency={view}
        transition={transition}
        className={cn(
          'tabular-nums transition-colors duration-200',
          classes.change
        )}
      >
        {changeTextOf(source.change)}
      </motion.span>
      <span aria-hidden='true' className={classes.zero} />
      <motion.span
        layout
        layoutDependency={view}
        transition={transition}
        aria-hidden='true'
        className={cn(
          'transition-colors duration-300',
          barToneOf(source, view),
          classes.bar
        )}
        style={barStyleOf(source, view, bounds)}
      />
    </li>
  );
}

export function SourceShift({
  title,
  note,
  sources,
  view,
  onViewChange,
  unit,
  period,
  className,
}: SourceShiftProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = glideOf(shouldReduceMotion);
  const bounds = boundsOf(sources);
  const ordered = orderedFor(view, sources);
  const reading = readingOf(view, sources, unit, period);
  const classes = VIEW_CLASSES[view];
  const summary = `${reading.headline}. ${reading.detail}.`;

  const rows: DataRow[] = ordered.map((source) => ({
    id: source.id,
    label: source.name,
    cells: [formatCount(source.value), changeTextOf(source.change)],
  }));

  return (
    <ChartCard
      title={title}
      note={note}
      summary={summary}
      className={className}
      actions={
        <Segments
          value={view}
          segments={VIEWS}
          onValueChange={onViewChange}
          label='How to read the sources'
        />
      }
    >
      <div className='flex flex-col'>
        <p className='text-sm font-medium'>
          <WrappingRoll text={reading.headline} />
        </p>
        <p className='text-muted-foreground text-xs tabular-nums'>
          <WrappingRoll text={reading.detail} />
        </p>
      </div>
      <ul className={classes.list} style={listStyleOf(view, ordered.length)}>
        {ordered.map((source) => (
          <SourceItem
            key={source.id}
            source={source}
            view={view}
            bounds={bounds}
            transition={transition}
          />
        ))}
      </ul>
      <DataTable
        caption={`${title}, ${period}`}
        columns={['Source', unit, 'Change on the period before']}
        rows={rows}
      />
    </ChartCard>
  );
}

const SOURCES: ShiftSource[] = [
  { id: 'search', name: 'Search', icon: SearchIcon, value: 4212, change: 12 },
  {
    id: 'direct',
    name: 'Direct',
    icon: MousePointerClickIcon,
    value: 2870,
    change: 3,
  },
  {
    id: 'referral',
    name: 'Referral',
    icon: Link2Icon,
    value: 1640,
    change: -4,
  },
  { id: 'social', name: 'Social', icon: Share2Icon, value: 1105, change: -9 },
  {
    id: 'newsletter',
    name: 'Newsletter',
    icon: MailIcon,
    value: 760,
    change: 31,
  },
];

export default function Chart08() {
  const [view, setView] = useState<ShiftView>('list');

  function resetDemo() {
    setView('list');
  }

  const steps: AutoplayStep[] = [
    { after: 2200, run: () => setView('bars') },
    { after: 2800, run: () => setView('change') },
    { after: 2800, run: () => setView('list') },
    { after: 1200, run: hold },
  ];
  const { ref, stopOnKeyboardFocus } = useChartDemo(steps, {
    loopAfter: 1600,
    onReset: resetDemo,
  });

  return (
    <div
      ref={ref}
      onFocus={stopOnKeyboardFocus}
      className='flex min-h-[23rem] w-full max-w-[26rem]'
    >
      <SourceShift
        title='Where visitors come from'
        note='Illustrative'
        sources={SOURCES}
        view={view}
        onViewChange={setView}
        unit='visits'
        period='this week'
        className='w-full'
      />
    </div>
  );
}

import { useId } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';

type ChartCardProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** One line that says what the chart shows, read by screen readers with the title. */
  summary: string;
  /** Controls that change what the chart draws: a period, a view. */
  actions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
};

/**
 * The surface every chart sits on. It is a query container, so a chart lays itself out by the
 * room it has, and it is positioned, so the hidden table of a chart never widens the page.
 */
export function ChartCard({
  title,
  note,
  summary,
  actions,
  className,
  children,
}: ChartCardProps) {
  const titleId = useId();
  const summaryId = useId();

  return (
    <section
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn(
        'bg-card hairline-ring ring-border @container relative flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <header className='flex min-h-7 flex-wrap items-center justify-between gap-x-3 gap-y-2'>
        <div className='flex min-w-0 items-center gap-2'>
          <h3 id={titleId} className='text-sm font-medium text-balance'>
            {title}
          </h3>
          {note && <Badge variant='secondary'>{note}</Badge>}
        </div>
        {actions}
      </header>
      {children}
      <p id={summaryId} className='sr-only'>
        {summary}
      </p>
    </section>
  );
}

/**
 * The four corners of a bar as numbers in a style object, where a layout animation can read them:
 * a bar that changes size keeps true corners instead of corners stretched with it.
 */
export type Corners = {
  borderTopLeftRadius: number;
  borderTopRightRadius: number;
  borderBottomRightRadius: number;
  borderBottomLeftRadius: number;
};

/** The end of a bar that carries its value is rounded by this much; its baseline end stays square. */
const END_RADIUS = 4;

function cornersOf(
  topLeft: number,
  topRight: number,
  bottomRight: number,
  bottomLeft: number
): Corners {
  return {
    borderTopLeftRadius: topLeft,
    borderTopRightRadius: topRight,
    borderBottomRightRadius: bottomRight,
    borderBottomLeftRadius: bottomLeft,
  };
}

export const SQUARE = cornersOf(0, 0, 0, 0);

export const ROUNDED_TOP = cornersOf(END_RADIUS, END_RADIUS, 0, 0);

export const ROUNDED_BOTTOM = cornersOf(0, 0, END_RADIUS, END_RADIUS);

export const ROUNDED_RIGHT = cornersOf(0, END_RADIUS, END_RADIUS, 0);

export const ROUNDED_LEFT = cornersOf(END_RADIUS, 0, 0, END_RADIUS);

/** A thin meter is rounded at both ends. */
export const ROUNDED_ENDS = cornersOf(2, 2, 2, 2);

export type DataRow = {
  id: string;
  /** The heading of the row: a day, a category, a step. */
  label: string;
  cells: readonly string[];
};

type DataTableProps = {
  caption: string;
  /** The heading of the label column first, then one per cell. */
  columns: readonly string[];
  rows: readonly DataRow[];
};

/**
 * The numbers a chart draws, as a table for screen readers. It is taken out of the flow, so the
 * piece it sits in has to be positioned: a hidden box inside an area that scrolls sideways widens
 * the page otherwise.
 */
export function DataTable({ caption, columns, rows }: DataTableProps) {
  return (
    <table className='sr-only'>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope='col'>
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            <th scope='row'>{row.label}</th>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

const LOCALE = 'en-US';

export const COUNT_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
};

export const SIGNED_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
  signDisplay: 'exceptZero',
};

export const USD_COMPACT_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COMPACT_FORMAT: Intl.NumberFormatOptions = {
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COUNT = new Intl.NumberFormat(LOCALE, COUNT_FORMAT);

const SIGNED = new Intl.NumberFormat(LOCALE, SIGNED_FORMAT);

const COMPACT = new Intl.NumberFormat(LOCALE, COMPACT_FORMAT);

const USD_COMPACT = new Intl.NumberFormat(LOCALE, USD_COMPACT_FORMAT);

const DAY = new Intl.DateTimeFormat(LOCALE, {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});

const MS_PER_DAY = 86_400_000;

export function formatCount(value: number) {
  return COUNT.format(value);
}

export function formatSigned(value: number) {
  return SIGNED.format(value);
}

export function formatCompact(value: number) {
  return COMPACT.format(value);
}

export function formatUsd(value: number) {
  return USD_COMPACT.format(value);
}

export function formatShare(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

/** A start at zero has no percentage to grow from: it reads as no change. */
export function percentChangeOf(current: number, previous: number) {
  if (previous === 0) {
    return 0;
  }
  const difference = current - previous;
  const ratio = difference / Math.abs(previous);
  return Math.round(ratio * 100);
}

export function changeWordsOf(percent: number, reference: string) {
  if (percent === 0) {
    return `level with ${reference}`;
  }
  const size = Math.abs(percent);
  if (percent > 0) {
    return `up ${size}% on ${reference}`;
  }
  return `down ${size}% on ${reference}`;
}

export function nounOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return singular;
  }
  return plural;
}

/**
 * One label per day, or per `everyDays` days for a weekly series. Days are counted in UTC so the
 * server and the browser write the same label.
 */
export function dayLabelsOf(firstDay: string, count: number, everyDays = 1) {
  const start = Date.parse(`${firstDay}T00:00:00Z`);
  const stride = everyDays * MS_PER_DAY;
  return Array.from({ length: count }, (_, index) => {
    const elapsed = index * stride;
    return DAY.format(start + elapsed);
  });
}

export type Domain = {
  min: number;
  max: number;
};

export type Scale = Domain & {
  step: number;
  ticks: number[];
};

const NICE_FACTORS = [1, 2, 5, 10];

const EMPTY_DOMAIN: Domain = { min: 0, max: 0 };

export function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(value, min);
  return Math.min(atLeastMin, max);
}

export function lerp(from: number, to: number, amount: number) {
  const span = to - from;
  return from + span * amount;
}

export function sumOf(values: readonly number[]) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

export function extentOf(values: readonly number[]): Domain {
  if (values.length === 0) {
    return EMPTY_DOMAIN;
  }
  let min = values[0];
  let max = values[0];
  for (const value of values) {
    min = Math.min(min, value);
    max = Math.max(max, value);
  }
  return { min, max };
}

/** Bars and areas are read from zero, so their domain always holds it. */
export function withZero(domain: Domain): Domain {
  const min = Math.min(domain.min, 0);
  const max = Math.max(domain.max, 0);
  return { min, max };
}

/** Where a value sits in a domain, from 0 at its lowest to 1 at its highest. */
export function ratioOf(value: number, domain: Domain) {
  const span = domain.max - domain.min;
  if (span === 0) {
    return 0;
  }
  const offset = value - domain.min;
  return offset / span;
}

/** A flat series still needs room above and below it to be drawn. */
function spanOf(domain: Domain) {
  const span = domain.max - domain.min;
  if (span > 0) {
    return span;
  }
  const size = Math.abs(domain.max);
  return Math.max(size, 1);
}

function niceStepOf(roughStep: number) {
  const logarithm = Math.log10(roughStep);
  const exponent = Math.floor(logarithm);
  const magnitude = 10 ** exponent;
  const factor = NICE_FACTORS.find((candidate) => {
    const candidateStep = candidate * magnitude;
    return candidateStep >= roughStep;
  });
  const safeFactor = factor ?? 10;
  return safeFactor * magnitude;
}

function decimalsOf(step: number) {
  const logarithm = Math.log10(step);
  const exponent = Math.floor(logarithm);
  return Math.max(0, -exponent);
}

/** Adding zero turns a negative zero into zero, which a number format would write as -0. */
function roundedTo(value: number, decimals: number) {
  const factor = 10 ** decimals;
  const scaled = Math.round(value * factor);
  const rounded = scaled / factor;
  return rounded + 0;
}

/** A scale with round ticks that holds the whole domain, in at most `maxLines` steps. */
export function niceScaleOf(domain: Domain, maxLines: number): Scale {
  const span = spanOf(domain);
  const roughStep = span / maxLines;
  const step = niceStepOf(roughStep);
  const decimals = decimalsOf(step);
  const stepsBelow = Math.floor(domain.min / step);
  const lowest = stepsBelow * step;
  const highestWanted = Math.max(domain.max, lowest + step);
  const stepsAbove = Math.ceil(highestWanted / step);
  const lineCount = stepsAbove - stepsBelow;
  const tickCount = lineCount + 1;
  const ticks = Array.from({ length: tickCount }, (_, index) => {
    const tick = lowest + index * step;
    return roundedTo(tick, decimals);
  });
  const lastIndex = ticks.length - 1;
  return { min: ticks[0], max: ticks[lastIndex], step, ticks };
}

/** Columns share the plot equally and a mark sits in the middle of its column. */
export function columnCenterOf(index: number, count: number) {
  const center = index + 0.5;
  return center / count;
}

export function columnIndexAt(ratio: number, count: number) {
  const rawIndex = Math.floor(ratio * count);
  const lastIndex = Math.max(count - 1, 0);
  return clamp(rawIndex, 0, lastIndex);
}

export function percentOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

/** The whole numbers that lead from one position to another: the start is left out, the end is kept. */
export function positionsTo(from: number, to: number) {
  const gap = to - from;
  const distance = Math.abs(gap);
  const direction = Math.sign(gap);
  return Array.from({ length: distance }, (_, index) => {
    const travelled = index + 1;
    const offset = travelled * direction;
    return from + offset;
  });
}

